const app = document.querySelector("#app");

const numberLink = (task) => `
  <a class="number-card" href="#/tasks/${task.number}" aria-label="Открыть задание №${task.number}">
    <span>${task.number}</span><small>Задание</small>
  </a>`;

const listItems = (items, className = "") =>
  `<ul class="tip-list ${className}">${items.map((item) => `<li>${item}</li>`).join("")}</ul>`;

const lessonBlock = (title, content) =>
  `<article class="lesson-block"><h2>${title}</h2>${content}</article>`;

const numberedList = (items) =>
  `<ol class="algorithm-list">${items.map((item) => `<li>${item}</li>`).join("")}</ol>`;

function prototypeBlocks(prototypes) {
  return prototypes.map((prototype) => `
    <article class="prototype-card">
      <h3>${prototype.title}</h3><p class="task-example">${prototype.prompt}</p>
      <p><strong>Ответ:</strong> ${prototype.answer}</p>
      <p><strong>Разбор:</strong> ${prototype.analysis}</p>
    </article>`).join("");
}

function practiceBlocks(task) {
  return task.practice.map((practice, index) => {
    const answerId = `task-${task.number}-practice-${index + 1}`;
    return `<article class="practice-item">
      <p>${practice.question}</p>
      <button class="button button-light reveal-button" type="button" data-reveal="${answerId}" aria-expanded="false">Показать ответ</button>
      <div class="revealed-answer" id="${answerId}" hidden>
        <p><strong>Ответ:</strong> ${practice.answer}</p><p><strong>Разбор:</strong> ${practice.explanation}</p>
      </div>
    </article>`;
  }).join("");
}

function homePage() {
  return `
    <section class="hero"><div class="container hero-grid"><div>
      <span class="eyebrow">Подготовка к ЕГЭ по географии</span>
      <h1>География — это понятно.</h1>
      <p class="lead">Выбери номер задания ЕГЭ и изучай теорию, алгоритмы и тренировочные примеры в удобном темпе.</p>
      <a class="button" href="#/tasks">Начать подготовку</a>
    </div><div class="map-card" aria-label="Декоративная иллюстрация карты">
      <span class="map-label">Твой маршрут к ЕГЭ</span><span class="route-line"></span><span class="pin pin-one"></span><span class="pin pin-two"></span>
    </div></div></section>
    <section class="section tasks-section"><div class="container">
      <div class="section-head"><div><h2>Все задания ЕГЭ</h2><p class="section-description">В экзаменационной работе 2026 года — 29 заданий. Выбери нужный номер.</p></div></div>
      <div class="number-grid">${tasks.map(numberLink).join("")}</div>
    </div></section>
    <section class="section"><div class="container"><h2>Почему с ГеоШагом удобно</h2><div class="benefits">
      <article class="benefit"><span class="benefit-icon">🧭</span><h3>По номерам КИМ</h3><p>Открывай именно то задание, которое хочешь повторить.</p></article>
      <article class="benefit"><span class="benefit-icon">💡</span><h3>Без лишнего</h3><p>Теория, алгоритм и лайфхаки собраны в одной понятной структуре.</p></article>
      <article class="benefit"><span class="benefit-icon">✍️</span><h3>С практикой</h3><p>Закрепляй знания на прототипах и тренировочных заданиях.</p></article>
    </div></div></section>`;
}

function tasksPage() {
  return `
    <section class="page-heading"><div class="container"><span class="eyebrow">ЕГЭ по географии · 2026</span><h1>Все 29 заданий</h1><p>Каждый номер ведёт на отдельную страницу с единым шаблоном подготовки.</p></div></section>
    <section class="all-tasks"><div class="container"><div class="number-grid">${tasks.map(numberLink).join("")}</div></div></section>`;
}

function taskNavigation(task) {
  const previous = tasks[task.number - 2];
  const next = tasks[task.number];
  return `<nav class="task-navigation" aria-label="Навигация по заданиям">
    <a href="#/tasks">← Все задания</a><span class="task-navigation-steps">
      ${previous ? `<a href="#/tasks/${previous.number}">← Предыдущее</a>` : "<span>← Предыдущее</span>"}
      ${next ? `<a href="#/tasks/${next.number}">Следующее →</a>` : "<span>Следующее →</span>"}
    </span>
  </nav>`;
}

function taskPage(task) {
  return `
    <section class="task-hero"><div class="container">
      ${taskNavigation(task)}
      <span class="eyebrow">ЕГЭ по географии · задание ${task.number}</span><h1>${task.title}</h1><p class="lead">${task.description}</p>
    </div></section>
    <section><div class="container content-grid"><div>
      ${lessonBlock("Что проверяет задание", `<p>${task.whatChecks}</p>`)}
      ${lessonBlock("Какой навык нужен", `<p>${task.skill}</p>`)}
      ${lessonBlock("Что нужно знать", `<p>${task.theory}</p>`)}
      ${lessonBlock("Как распознать задание", `<p>${task.recognition}</p>`)}
      ${lessonBlock("Пошаговый алгоритм решения", `<p>${task.howToSolve}</p>${numberedList(task.algorithm)}`)}
      ${task.answerFormat ? lessonBlock("Как оформить развёрнутый ответ", `<p>${task.answerFormat}</p>`) : ""}
      ${task.assessment ? lessonBlock("Критерии и особенности оценивания", `<p>${task.assessment}</p>`) : ""}
      ${lessonBlock("Лайфхаки", listItems(task.tips))}
      ${lessonBlock("Типичные ошибки", listItems(task.commonMistakes, "error-list"))}
      ${lessonBlock("Прототипы и разбор", prototypeBlocks(task.prototypes))}
      ${lessonBlock("Тренировка", practiceBlocks(task))}
      ${lessonBlock("Что запомнить", listItems(task.remember))}
      ${taskNavigation(task)}
    </div><aside class="practice-card"><p class="practice-label">САМОПОДГОТОВКА</p><h2>Работа над заданием</h2><p>Сначала реши задания из блока «Тренировка» самостоятельно, а затем открывай ответы и разбирай ход решения.</p></aside></div></section>`;
}

function notFoundPage() {
  return `<section class="page-heading"><div class="container"><span class="eyebrow">Страница не найдена</span><h1>Похоже, здесь пока нет маршрута.</h1><a class="button" href="#/">На главную</a></div></section>`;
}

function render() {
  const route = location.hash.slice(1) || "/";
  const taskMatch = route.match(/^\/tasks\/(\d+)$/);
  const task = taskMatch && tasks.find(({ number }) => number === Number(taskMatch[1]));
  app.innerHTML = route === "/" ? homePage() : route === "/tasks" ? tasksPage() : task ? taskPage(task) : notFoundPage();

  document.querySelectorAll("[data-nav]").forEach((link) => {
    link.classList.toggle("active", link.dataset.nav === (route === "/" ? "home" : "tasks"));
  });
  document.querySelectorAll("[data-reveal]").forEach((button) => {
    button.addEventListener("click", () => {
      const answer = document.querySelector(`#${button.dataset.reveal}`);
      const isHidden = answer.hidden;
      answer.hidden = !isHidden;
      button.setAttribute("aria-expanded", String(isHidden));
      button.textContent = isHidden ? "Скрыть ответ" : "Показать ответ";
    });
  });
  window.scrollTo({ top: 0, behavior: "instant" });
}

window.addEventListener("hashchange", render);
render();
